// Record the accepted source finisher's output for the deterministic browser
// finishing fixture inputs. Runs the production postprocess-retained-mesh.py
// consumer in mlx-surface-preserving mode on the exact generated bytes.
//
// node models/trellis2/export-mesh-finishing-fixtures.mjs --python <venv python> \
//   --source-root <TRELLIS2MLX checkout> --expected-source-commit <sha> --work <dir> [--out <json>]
import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {MESH_FINISHING_CASES} from './tests/mesh-finishing-fixture.js';

const here=path.dirname(fileURLToPath(import.meta.url));
const args=new Map();for(let i=2;i<process.argv.length;i+=2)args.set(process.argv[i],process.argv[i+1]);
for(const key of ['--python','--source-root','--expected-source-commit','--work'])if(!args.get(key))throw Error(key+' required');
const out=args.get('--out')??path.join(here,'tests/fixtures/mesh-finishing-source.json');
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const cases={};
for(const [name,spec] of Object.entries(MESH_FINISHING_CASES)){
  const dir=path.resolve(args.get('--work'),name),input=path.join(dir,'raw'),result=path.join(dir,'source');
  await fs.mkdir(input,{recursive:true});
  const {vertices,triangles}=spec.build(),vb=Buffer.from(vertices.buffer),tb=Buffer.from(triangles.buffer);
  await fs.writeFile(path.join(input,'vertices.f32'),vb);await fs.writeFile(path.join(input,'triangles.u32'),tb);
  const row=(file,dtype,count,bytes)=>({file,dtype,shape:[count,3],byteLength:bytes.length,sha256:sha(bytes)});
  await fs.writeFile(path.join(input,'manifest.json'),JSON.stringify({schema:'trellis2.raw-mesh-input.v0',
    vertices:row('vertices.f32','float32',vertices.length/3,vb),triangles:row('triangles.u32','uint32',triangles.length/3,tb)},null,1));
  execFileSync(args.get('--python'),[path.join(here,'postprocess-retained-mesh.py'),'--source-root',args.get('--source-root'),
    '--expected-source-commit',args.get('--expected-source-commit'),'--input',path.join(input,'manifest.json'),'--output',result,
    '--target-faces',String(spec.targetFaces),'--cleanup-mode','mlx-surface-preserving'],{stdio:'inherit',env:{...process.env,PYTHONDONTWRITEBYTECODE:'1'}});
  // Also record the native simplifier's first pass in full F64, where every
  // contracted multiply-add is still visible before the F32 emission.
  const ratio=spec.targetFaces/(triangles.length/3),simplified=path.join(dir,'simplify-pass0');
  let simplify=null;
  if(ratio<1){
    execFileSync(args.get('--python'),['-c',`import sys,numpy as np,fast_simplification as fs
v=np.fromfile(sys.argv[1],'<f4').reshape(-1,3);f=np.fromfile(sys.argv[2],'<u4').reshape(-1,3)
p,t=fs.simplify(v,f,target_reduction=1.0-float(sys.argv[3]))
np.ascontiguousarray(p,'<f8').tofile(sys.argv[4]+'-points.f64');np.ascontiguousarray(t,'<i4').tofile(sys.argv[4]+'-triangles.i32')`,
      path.join(input,'vertices.f32'),path.join(input,'triangles.u32'),String(ratio),simplified],{env:{...process.env,PYTHONDONTWRITEBYTECODE:'1'}});
    const points=await fs.readFile(simplified+'-points.f64'),tris=await fs.readFile(simplified+'-triangles.i32');
    simplify={targetReduction:1.0-ratio,points:points.length/24,faces:tris.length/12,pointsSha256:sha(points),trianglesSha256:sha(tris)};
  }
  const report=JSON.parse(await fs.readFile(path.join(result,'report.json')));
  if(report.status!=='succeeded')throw Error(name+' source finisher failed: '+JSON.stringify(report.error));
  cases[name]={targetFaces:spec.targetFaces,input:{vertices:vertices.length/3,faces:triangles.length/3,verticesSha256:sha(vb),trianglesSha256:sha(tb)},
    ...(simplify?{simplifyPass0:simplify}:{}),
    output:{vertices:report.outputVertices,faces:report.outputFaces,verticesSha256:report.arrays.vertices.sha256,trianglesSha256:report.arrays.triangles.sha256},
    sourceEvents:report.events.map(e=>e.message.trim())};
  if(!cases[name].sourceEvents.length)delete cases[name].sourceEvents;
}
const first=Object.values(cases)[0]&&JSON.parse(await fs.readFile(path.resolve(args.get('--work'),Object.keys(cases)[0],'source/report.json')));
await fs.writeFile(out,JSON.stringify({schema:'trellis2.mesh-finishing-source-fixture.v0',
  route:'postprocess-retained-mesh.py --cleanup-mode mlx-surface-preserving',
  source:{commit:first.source.commit,generateSha256:first.source.generateSha256,cleanupSha256:first.source.cleanupSha256,packages:first.source.packages},
  cases},null,1)+'\n');
console.log(JSON.stringify(cases,null,1));
